use crate::{catalog,model::*,rules::*,unit_support::*};
fn setup(grave:bool)->(Game,String){let mut g=game();fund(&mut g,0,"JC042",3);let c=g.make_card("CQ14",0);let id=c.id.clone();if grave{field(&mut g,"CQ12",0);g.players[0].graveyard.push(c);let red=g.make_card("JC042",0);g.players[0].hand.push(red);}else{g.players[0].hand.push(c);}(g,id)}
fn play(g:&mut Game,id:&str){act(g,0,Action{card_id:Some(id.into()),..Action::new("play")});}
fn top(g:&mut Game){for _ in 0..20{if g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
#[test]fn cq14_original_closed_and_three_total(){assert_current_serial_catalog();assert!(!catalog::card("CQ14").supported);let(mut g,id)=setup(false);play(&mut g,&id);choose(&mut g,vec!["0:0".into(),"0:1".into(),"1:0".into()]);top(&mut g);let tokens=g.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition=="TK008").collect::<Vec<_>>();assert_eq!(tokens.len(),3);assert!(tokens.iter().all(|c|c.exhausted));restore(&mut g);}
#[test]fn cq14_zero_generation_legal_and_not_three_per_region(){let(mut g,id)=setup(false);play(&mut g,&id);choose(&mut g,vec![]);top(&mut g);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="TK008"));}
#[test]fn cq14_grave_replay_discards_one_red_and_requires_actual_character(){let(mut g,id)=setup(true);assert!(g.legal_actions(0).iter().any(|a|a.action.kind=="play"&&a.action.card_id.as_deref()==Some(&id)));play(&mut g,&id);choose(&mut g,vec!["0:0".into()]);let p=g.pending.clone().unwrap();assert_eq!(p.choice.min,Some(1));let red=p.choice.options[0].id.clone();choose(&mut g,vec![red]);assert!(g.players[0].hand.is_empty());top(&mut g);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK008").count(),1);let(mut g,id)=setup(true);g.regions[0].cards[0].face_down=true;reject(&mut g,0,Action{card_id:Some(id),..Action::new("play")});}
#[test]fn cq14_replaced_region_cancels_original_targets_after_restore(){let(mut g,id)=setup(false);play(&mut g,&id);choose(&mut g,vec!["0:0".into(),"1:0".into()]);g.regions[0].card=g.make_card("DQJC115",0);restore(&mut g);top(&mut g);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="TK008"));}
#[test]fn cq14_corrupt_pending_counts_and_actual_missing_frame_rejected(){let(mut g,id)=setup(false);play(&mut g,&id);let mut x=g.clone();x.pending.as_mut().unwrap().choice.max=Some(9);assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());choose(&mut g,vec!["0:0".into()]);for n in 0..3{let mut x=g.clone();match n{0=>x.stack.last_mut().unwrap().frame=None,1=>if let Op::CQ14Summon{counts,..}=&mut x.stack.last_mut().unwrap().frame.as_mut().unwrap().steps[0].op{counts[0]=4},_=>x.stack.last_mut().unwrap().frame.as_mut().unwrap().source.card.definition="JC001".into()};assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(&g);r.game=x;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}}
#[test]fn cq_pair_native_natural_export(){use crate::{deck,abi112_review_play_tests::Trace};fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="cq12-cq14-private".into();d.society_id=None;d.core_card_id=None;d.cards=[("CQ12",3),("CQ14",3),("CQ11",3),("JC042",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["CQ12","CQ14","CQ11"].contains(&c.id.as_str()){c.supported=true;}}let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("cq-pair".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
let(seed,g)=(1..16385).find_map(|seed|{let g=construct(seed);let h=&g.players[0].hand;(["CQ12","CQ14","CQ11"].iter().all(|id|h.iter().any(|c|c.definition==*id))&&h.iter().filter(|c|c.definition=="JC042").count()>=2).then_some((seed,g))}).expect("bounded natural initial cards");let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"cq-pair-natural".into(),901);let mut omen=false;let mut first=false;let mut replay=false;let mut generated=false;
for _ in 0..2600{if let Some(p)=t.room.game.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Forecast{..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});continue;}let ids=match p.choice.kind.as_str(){"cq12-sacrifice"=>p.choice.options.iter().take(2).map(|o|o.id.clone()).collect(),"cq14-regions"=>p.choice.options.iter().filter(|o|o.id.starts_with("0:")).take(3).map(|o|o.id.clone()).collect(),"cq14-red"=>p.choice.options.iter().take(1).map(|o|o.id.clone()).collect(),_=>if matches!(&p.resolution,ChoiceResolution::Declare{declaration,..}if declaration.source.card.definition=="CQ11"){vec!["accept".into()]}else{let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&["CQ12","CQ14","CQ11","JC042"].contains(&c.definition.as_str())));opts.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}};t.choose(ids);continue;}if replay&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let name=|a:&Action,id:&str|a.card_id.as_ref().is_some_and(|key|g.players[0].hand.iter().chain(g.regions.iter().flat_map(|r|&r.cards)).any(|c|&c.id==key&&c.definition==id));let reds=g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="红").count();let live=g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="CQ12"&&!c.face_down&&c.controller==0);generated|=g.regions.iter().flat_map(|r|&r.cards).any(|c|c.generated.is_some()&&c.definition=="TK008");let chosen=if !omen&&reds>=2&&g.players[0].assets.len()>=11{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::cq12::OMEN))}else{None}.or_else(||if reds<2{legal.iter().find(|a|a.action.kind=="asset"&&name(&a.action,"JC042"))}else{None}).or_else(||if g.players[0].assets.len()<11{legal.iter().find(|a|a.action.kind=="asset"&&name(&a.action,"JC125"))}else{None}).or_else(||if !omen&&g.players[0].assets.len()>=11&&!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.controller==0&&!c.face_down){legal.iter().find(|a|a.action.kind=="deploy"&&name(&a.action,"JC125")&&a.action.region==Some(0))}else{None}).or_else(||if omen&&!live{legal.iter().find(|a|a.action.kind=="deploy"&&name(&a.action,"CQ12")&&a.action.region==Some(0))}else{None}).or_else(||if live{legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|if first{g.bq095_self_grave_sources(0).iter().any(|c|&c.id==id&&c.definition=="CQ14")}else{g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="CQ14")}))}else{None});if let Some(a)=chosen{let a=a.action.clone();if a.ability_id.as_deref()==Some(crate::cq12::OMEN){omen=true;}if a.kind=="play"{if first{replay=true}else{first=true}}t.action(0,a);}else{t.pass();}}
if !(omen&&first&&replay&&generated){eprintln!("incomplete hand={:?} assets={:?} window={:?}",t.room.game.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.players[0].assets.iter().map(|c|(&c.definition,c.exhausted)).collect::<Vec<_>>(),t.room.game.window);}
assert!(omen&&first&&replay&&generated,"natural chain incomplete omen={omen} first={first} replay={replay} generated={generated} turn={}",t.room.game.turn);assert!(t.room.game.stack.is_empty()&&t.room.game.pending.is_none());let mut v=t.value();let first_step=v["steps"].as_array().unwrap().iter().position(|s|s["command"]["action"]["action"]["abilityId"]==crate::cq12::OMEN).expect("actual omen command");v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true,"firstMechanismStep":first_step});for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"].as_str().unwrap());s["duplicate"]=serde_json::to_value(d).unwrap();}v["catalog"]=serde_json::to_value(catalog::catalog()).unwrap();let mut b=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/cq12.rs",include_bytes!("cq12.rs").as_slice()),("rust-game/src/cq14.rs",include_bytes!("cq14.rs").as_slice()),("rust-game/src/cq12_tests.rs",include_bytes!("cq12_tests.rs").as_slice()),("rust-game/src/cq14_tests.rs",include_bytes!("cq14_tests.rs").as_slice())]{b["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}v["sourceBindings"]=b;if let Ok(path)=std::env::var("CQ_PAIR_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&v).unwrap()).unwrap();}}
